using System; using System.Data.SqlClient; using System.IO;
namespace AshkanPharmacy.Core { public static class BackupService { public static void Backup(string path) { if(string.IsNullOrWhiteSpace(path)) throw new ArgumentException("Backup path is required."); var dir=Path.GetDirectoryName(path); if(!string.IsNullOrEmpty(dir)&&!Directory.Exists(dir)) Directory.CreateDirectory(dir); using(var c=Database.Open()) using(var cmd=new SqlCommand("BACKUP DATABASE [AshkanPharmacyDb] TO DISK=@p WITH INIT, CHECKSUM",c)){cmd.Parameters.AddWithValue("@p",path);cmd.CommandTimeout=120;cmd.ExecuteNonQuery();} } } }